arguments.command:
python -c "
import py_compile, glob, sys
errors = []
for f in sorted(glob.glob('harness/**/*.py', recursive=True)):
    try:
        py_compile.compile(f, doraise=True)
    except py_compile.PyCompileError as e:
        errors.append(str(e))
if errors:
    for e in errors:
        print(e)
    sys.exit(1)
else:
    print('All files parse OK')
"
